# Purpose: tests for ds.data.raw.logfire's row handling: the query API's JSON rows become
#          typed frames (timestamps arrive as ISO text) and a missing key is its own error.
# Usage: uv run pytest tests/ds/data/test_logfire.py
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt

import polars as pl
import pytest
from ds.data.raw import logfire
from ds.settings import Settings

UTC = pl.Datetime("us", "UTC")


def test_frame_parses_iso_timestamps():
    rows = {"rows": [["2026-11-14T22:00:00Z", 3], ["2026-11-08T23:37:32.007140Z", None]]}
    frame = logfire._frame(rows, {"hour": UTC, "requests": pl.Int64})
    assert frame.schema == {"hour": UTC, "requests": pl.Int64}
    assert frame["hour"][0] == dt.datetime(2026, 11, 14, 22, tzinfo=dt.UTC)
    assert frame["hour"][1].microsecond == 7140


def test_frame_without_rows_keeps_the_schema():
    frame = logfire._frame({"rows": []}, {"hour": UTC, "cost": pl.Float64})
    assert frame.is_empty()
    assert frame.schema == {"hour": UTC, "cost": pl.Float64}


def test_ai_spend_without_the_key_asks_for_it(monkeypatch: pytest.MonkeyPatch):
    monkeypatch.setattr(logfire, "get_settings", Settings)
    with pytest.raises(logfire.LogfireKeyMissingError, match="ds settings sync"):
        logfire.ai_spend()
